package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

const (
	keyPrefix = "visitor-tally/counter/"
	barrierPrefix = "visitor-tally/barrier/"
)

type countBody struct {
	maelstrom.MessageBody
	Visitors int64 `json:"visitors"`
}

type totalBody struct {
	maelstrom.MessageBody
}

type requestID struct {
	client string
	msgID  int
}

type server struct {
	node *maelstrom.Node
	kv   *maelstrom.KV

	// A node is the sole writer of its own counter key.  Serializing requests
	// also makes the values written for that key strictly increasing.
	mu sync.Mutex

	local       int64
	barrier     int64
	nodeIDs     []string
	seenCounts  map[requestID]bool
}

func main() {
	node := maelstrom.NewNode()
	kv := maelstrom.NewSeqKV(node)

	s := &server{
		node:       node,
		kv:         kv,
		seenCounts: make(map[requestID]bool),
	}

	node.Handle("init", func(msg maelstrom.Message) error {
		s.nodeIDs = append([]string(nil), node.NodeIDs()...)
		return nil
	})

	node.Handle("count", s.handleCount)
	node.Handle("total", s.handleTotal)

	if err := node.Run(); err != nil {
		log.Fatalf("node stopped: %v", err)
	}
}

func (s *server) handleCount(msg maelstrom.Message) error {
	var body countBody
	if err := unmarshalBody(msg, &body); err != nil {
		return maelstrom.NewRPCError(maelstrom.MalformedRequest, err.Error())
	}
	if body.Visitors < 0 {
		return maelstrom.NewRPCError(maelstrom.MalformedRequest, "visitors must be non-negative")
	}

	id := requestID{client: msg.Src, msgID: body.MsgID}

	s.mu.Lock()
	if s.seenCounts[id] {
		s.mu.Unlock()
		return s.node.Reply(msg, map[string]any{"type": "counted"})
	}
	// Remember the request before doing the write.  If the write fails, remove
	// it again so that a repeated request can retry the operation.
	s.seenCounts[id] = true
	s.local += body.Visitors
	value := s.local
	s.mu.Unlock()

	ctx, cancel := context.WithTimeout(context.Background(), 4500*time.Millisecond)
	defer cancel()

	key := keyPrefix + s.node.ID()
	if err := s.writeCounter(ctx, key, value); err != nil {
		s.mu.Lock()
		delete(s.seenCounts, id)
		s.mu.Unlock()
		return fmt.Errorf("publish counter: %w", err)
	}

	return s.node.Reply(msg, map[string]any{"type": "counted"})
}

// writeCounter publishes a cumulative counter value.  Retrying is useful when
// a response is lost: the value is cumulative, so retrying the same value is
// idempotent.
func (s *server) writeCounter(ctx context.Context, key string, value int64) error {
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		if err := s.kv.Write(ctx, key, value); err == nil {
			return nil
		} else {
			lastErr = err
		}
		if ctx.Err() != nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	return lastErr
}

func (s *server) handleTotal(msg maelstrom.Message) error {
	var body totalBody
	if err := unmarshalBody(msg, &body); err != nil {
		return maelstrom.NewRPCError(maelstrom.MalformedRequest, err.Error())
	}

	ctx, cancel := context.WithTimeout(context.Background(), 4500*time.Millisecond)
	defer cancel()

	// A seq-kv read may observe an older state.  First perform a changing write
	// from this client.  Sequential consistency then guarantees that the
	// following reads cannot go back before this point in the store's total
	// order.  This is a read barrier, and also makes all previously committed
	// counter writes visible.
	if err := s.writeBarrier(ctx); err != nil {
		return fmt.Errorf("read barrier: %w", err)
	}

	s.mu.Lock()
	ids := append([]string(nil), s.nodeIDs...)
	local := s.local
	s.mu.Unlock()

	var total int64
	for _, id := range ids {
		if id == s.node.ID() {
			// The local cumulative value also covers a count whose store write
			// succeeded but whose acknowledgement was lost.  Such a count is
			// indeterminate from the client's point of view and is therefore
			// allowed to be included.
			total += local
			continue
		}

		value, err := s.readCounter(ctx, keyPrefix+id)
		if err != nil {
			return fmt.Errorf("read counter for %s: %w", id, err)
		}
		total += value
	}

	return s.node.Reply(msg, map[string]any{
		"type":            "total_is",
		"visitors_so_far": total,
	})
}

// writeBarrier writes a fresh value on every attempt.  A changing write is
// forced to use the newest seq-kv state and advances this client's read
// position; a repeated no-op write would not necessarily do so.
func (s *server) writeBarrier(ctx context.Context) error {
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		s.mu.Lock()
		s.barrier++
		value := s.barrier
		s.mu.Unlock()

		key := barrierPrefix + s.node.ID()
		if err := s.kv.Write(ctx, key, value); err == nil {
			return nil
		} else {
			lastErr = err
		}
		if ctx.Err() != nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	return lastErr
}

func (s *server) readCounter(ctx context.Context, key string) (int64, error) {
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		value, err := s.kv.Read(ctx, key)
		if err == nil {
			switch v := value.(type) {
			case int:
				return int64(v), nil
			case int64:
				return v, nil
			case float64:
				return int64(v), nil
			default:
				return 0, fmt.Errorf("unexpected counter value %T", value)
			}
		}

		if maelstrom.ErrorCode(err) == maelstrom.KeyDoesNotExist {
			return 0, nil
		}
		lastErr = err
		if ctx.Err() != nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	return 0, lastErr
}

func unmarshalBody(msg maelstrom.Message, dst any) error {
	if len(msg.Body) == 0 {
		return errors.New("empty message body")
	}
	return jsonUnmarshal(msg.Body, dst)
}

// jsonUnmarshal is kept in a helper so all protocol parsing has one place.
func jsonUnmarshal(data []byte, dst any) error {
	return json.Unmarshal(data, dst)
}

